var piano=document.getElementById('pianoWrap');
var ww=100/WKEYS.length;
WKEYS.forEach(function(k,i){
  var el=document.createElement('div');
  el.className='wkey';
  el.style.cssText='left:'+(i*ww)+'%;width:'+(ww-.3)+'%;height:100%;';
  el.innerHTML='<span class="key-label">'+k.n+'</span>';
  el.onpointerdown=function(){
    playNote(k.m,0.6,'triangle',0.45);
    document.getElementById('noteDisplay').textContent='♪ '+k.n+' (MIDI '+k.m+')';
    el.classList.add('pressed');setTimeout(function(){el.classList.remove('pressed')},200);
  };
  piano.appendChild(el);
});
BKEYS.forEach(function(k){
  var el=document.createElement('div');
  el.className='bkey';
  el.style.cssText='left:'+((k.wi+0.65)*ww)+'%;width:'+(ww*.58)+'%;height:60%;';
  el.onpointerdown=function(e){
    e.stopPropagation();
    playNote(k.m,0.6,'triangle',0.4);
    document.getElementById('noteDisplay').textContent='♪ '+k.n+' (MIDI '+k.m+')';
    el.classList.add('pressed');setTimeout(function(){el.classList.remove('pressed')},200);
  };
  piano.appendChild(el);
});

